/* =========================================================
   Puff · 婴儿黄 × iOS 超淡磨砂玻璃
   Baby Yellow / Milk Glass / Soft UI
   ========================================================= */


/* =========================
   —— 全局 / 入口列表 ——
   ========================= */

.off-app {
  --off-list-bg:
    linear-gradient(
      145deg,
      rgba(255, 253, 239, 0.96),
      rgba(255, 252, 246, 0.91)
    );

  --off-list-border: rgba(255, 255, 255, 0.90);
  --off-list-radius: 22px;
  --off-list-ava-size: 52px;

  /* 婴儿黄 */
  --off-yellow: #f3df91;
  --off-yellow-light: #fff5c9;
  --off-yellow-soft: rgba(249, 228, 151, 0.20);

  /* iOS 白色玻璃 */
  --off-glass: rgba(255, 255, 255, 0.64);
  --off-glass-heavy: rgba(255, 255, 255, 0.80);
  --off-glass-border: rgba(255, 255, 255, 0.86);

  --off-glass-shadow:
    0 8px 30px rgba(130, 112, 55, 0.045),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
}


/* =========================
   —— 深色模式 ——
   ========================= */

html[data-theme="dark"] .off-app {
  --off-list-bg:
    linear-gradient(
      145deg,
      rgba(48, 47, 38, 0.96),
      rgba(37, 36, 32, 0.94)
    );

  --off-list-border:
    rgba(255, 255, 255, 0.10);

  --off-yellow:
    #e5ce79;

  --off-yellow-light:
    rgba(245, 221, 137, 0.18);

  --off-yellow-soft:
    rgba(245, 221, 137, 0.12);

  --off-glass:
    rgba(45, 44, 39, 0.60);

  --off-glass-heavy:
    rgba(48, 47, 42, 0.82);

  --off-glass-border:
    rgba(255, 255, 255, 0.10);

  --off-glass-shadow:
    0 8px 30px rgba(0, 0, 0, 0.30),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}


/* =========================
   —— 入口筛选 ——
   ========================= */

.off-inbox-filter {
  background:
    rgba(255, 255, 255, 0.48);

  border:
    1px solid rgba(255, 255, 255, 0.78);

  border-radius:
    999px;

  backdrop-filter:
    blur(20px) saturate(120%);

  -webkit-backdrop-filter:
    blur(20px) saturate(120%);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

.off-inbox-filter button {
  color:
    #aaa38e;

  background:
    transparent;

  border-radius:
    999px;

  transition:
    background 0.2s ease,
    color 0.2s ease,
    box-shadow 0.2s ease;
}

.off-inbox-filter button.on {
  color:
    #766b42;

  background:
    linear-gradient(
      135deg,
      #fff0ad,
      #f7e19a
    );

  box-shadow:
    0 4px 12px rgba(225, 198, 105, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.78);
}


/* 深色筛选 */

html[data-theme="dark"] .off-inbox-filter {
  background:
    rgba(255, 255, 255, 0.07);

  border-color:
    rgba(255, 255, 255, 0.10);
}

html[data-theme="dark"] .off-inbox-filter button {
  color:
    #aaa697;
}

html[data-theme="dark"] .off-inbox-filter button.on {
  color:
    #fff8d9;

  background:
    linear-gradient(
      135deg,
      #dfc77a,
      #caae61
    );

  box-shadow:
    0 4px 14px rgba(190, 160, 75, 0.24);
}


/* =========================
   —— 入口列表 ——
   ========================= */

.off-list {
  background:
    var(--off-list-bg);

  border:
    1px solid var(--off-list-border);

  border-radius:
    var(--off-list-radius);

  overflow:
    hidden;

  backdrop-filter:
    blur(28px) saturate(120%);

  -webkit-backdrop-filter:
    blur(28px) saturate(120%);

  box-shadow:
    var(--off-glass-shadow);
}

.off-list-btn {
  padding:
    15px 14px 15px 16px;

  transition:
    background 0.2s ease,
    transform 0.15s ease;
}

.off-list-btn:hover {
  background:
    rgba(250, 230, 157, 0.075);
}

.off-list-btn:active {
  transform:
    scale(0.985);
}


/* 头像 */

.off-list-ava {
  width:
    var(--off-list-ava-size);

  height:
    var(--off-list-ava-size);

  border-radius:
    50%;

  border:
    2px solid rgba(255, 255, 255, 0.92);

  box-shadow:
    0 3px 12px rgba(120, 105, 60, 0.055),
    0 0 0 3px rgba(255, 237, 174, 0.18);
}


/* 文字 */

.off-list-body strong {
  font-size:
    1.3rem;

  color:
    #4a473d;

  font-weight:
    600;
}

.off-list-body span {
  opacity:
    0.68;

  color:
    #979180;
}


/* 新消息 */

.off-list-go.is-new {
  font-size:
    20px;

  font-weight:
    300;

  color:
    #e3c967;

  text-shadow:
    0 2px 8px rgba(226, 201, 105, 0.18);
}


/* 深色文字 */

html[data-theme="dark"] .off-list-body strong {
  color:
    #f4f0df;
}

html[data-theme="dark"] .off-list-body span {
  color:
    #b5af9e;
}

html[data-theme="dark"] .off-list-go.is-new {
  color:
    #dec779;
}


/* =========================================================
   —— 当面共处 ——
   ========================================================= */

.off-app.off-app-session {
  --off-card-user:
    linear-gradient(
      135deg,
      rgba(255, 244, 193, 0.68),
      rgba(255, 250, 225, 0.58)
    );

  --off-card-peer:
    rgba(255, 255, 255, 0.66);

  --off-card-border:
    rgba(255, 255, 255, 0.86);

  --off-card-shadow:
    0 8px 30px rgba(125, 105, 55, 0.045),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);

  --off-prose-font:
    var(--display),
    "Noto Serif SC",
    "Source Han Serif SC",
    Georgia,
    serif;

  --off-dock-bg:
    rgba(255, 254, 246, 0.72);

  color:
    var(--ink);
}


/* 深色当面页 */

html[data-theme="dark"] .off-app.off-app-session {
  --off-card-user:
    linear-gradient(
      135deg,
      rgba(104, 91, 52, 0.62),
      rgba(58, 55, 44, 0.70)
    );

  --off-card-peer:
    rgba(45, 44, 39, 0.64);

  --off-card-border:
    rgba(255, 255, 255, 0.10);

  --off-card-shadow:
    0 8px 30px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);

  --off-dock-bg:
    rgba(34, 33, 29, 0.74);
}


/* =========================
   —— 无壁纸背景 ——
   ========================= */

.off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {
  background:
    radial-gradient(
      circle at 15% 15%,
      rgba(255, 239, 175, 0.46),
      transparent 35%
    ),
    radial-gradient(
      circle at 85% 80%,
      rgba(255, 247, 211, 0.64),
      transparent 40%
    ),
    #f8f6ee;
}


html[data-theme="dark"]
.off-app.off-app-session:not(:has(.off-stage.has-bg))
.off-stage {
  background:
    radial-gradient(
      circle at 15% 15%,
      rgba(180, 153, 70, 0.24),
      transparent 35%
    ),
    #211f1a;
}


/* =========================
   —— 当面顶栏 ——
   ========================= */

.off-app.off-app-session .off-stage-head {
  background:
    rgba(255, 253, 246, 0.60);

  border-bottom:
    1px solid rgba(255, 255, 255, 0.76);

  backdrop-filter:
    blur(26px) saturate(120%);

  -webkit-backdrop-filter:
    blur(26px) saturate(120%);

  box-shadow:
    0 4px 18px rgba(125, 105, 55, 0.035);
}

html[data-theme="dark"]
.off-app.off-app-session .off-stage-head {
  background:
    rgba(34, 33, 29, 0.64);

  border-bottom-color:
    rgba(255, 255, 255, 0.08);
}

.off-app.off-app-session .off-stage-scene {
  font-weight:
    500;

  letter-spacing:
    0.04em;
}


/* =========================
   —— 日记 / 消息卡片 ——
   ========================= */

.off-app.off-app-session .off-passage-sheet {
  background:
    var(--off-card-peer);

  border:
    1px solid var(--off-card-border);

  box-shadow:
    var(--off-card-shadow);

  border-radius:
    20px;

  backdrop-filter:
    blur(24px) saturate(120%);

  -webkit-backdrop-filter:
    blur(24px) saturate(120%);

  overflow:
    hidden;
}


/* 自己的消息 */

.off-app.off-app-session
.off-passage.is-me
.off-passage-sheet {
  background:
    var(--off-card-user);

  border-color:
    rgba(242, 218, 143, 0.38);

  box-shadow:
    0 8px 26px rgba(220, 190, 95, 0.065),
    inset 0 1px 0 rgba(255, 255, 255, 0.88);
}


/* =========================
   —— 推演 Chip ——
   ========================= */

.off-app .off-thinking-chip {
  background:
    rgba(255, 255, 255, 0.50);

  color:
    #968e7c;

  border:
    1px solid rgba(255, 255, 255, 0.72);

  border-radius:
    999px;

  padding:
    3px 11px;

  font-size:
    11px;

  letter-spacing:
    0.04em;

  backdrop-filter:
    blur(14px);

  -webkit-backdrop-filter:
    blur(14px);
}

html[data-theme="dark"]
.off-app .off-thinking-chip {
  background:
    rgba(255, 255, 255, 0.07);

  color:
    #b5ae9e;

  border-color:
    rgba(255, 255, 255, 0.08);
}


/* =========================
   —— 正文 ——
   ========================= */

.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain {
  font-family:
    var(--off-prose-font);

  line-height:
    1.85;

  font-size:
    14.5px;

  color:
    var(--ink);
}

.off-app.off-app-session .off-prose-dial {
  font-family:
    var(--off-prose-font);

  line-height:
    1.85;

  font-size:
    14.5px;

  font-style:
    normal;

  font-weight:
    500;
}

.off-app.off-app-session
.off-passage.is-me
.off-prose-dial {
  font-weight:
    400;
}


/* =========================
   —— 底部 Dock ——
   ========================= */

.off-app.off-app-session .off-stage-dock {
  background:
    var(--off-dock-bg);

  backdrop-filter:
    blur(28px) saturate(125%);

  -webkit-backdrop-filter:
    blur(28px) saturate(125%);

  border-top:
    1px solid rgba(255, 255, 255, 0.78);

  box-shadow:
    0 -8px 30px rgba(125, 105, 55, 0.035);
}

html[data-theme="dark"]
.off-app.off-app-session .off-stage-dock {
  border-top-color:
    rgba(255, 255, 255, 0.08);

  box-shadow:
    0 -8px 30px rgba(0, 0, 0, 0.18);
}


/* =========================
   —— 输入框 ——
   ========================= */

.off-compose-bar {
  background:
    rgba(255, 255, 255, 0.72);

  border:
    1px solid rgba(255, 255, 255, 0.90);

  border-radius:
    999px;

  backdrop-filter:
    blur(24px) saturate(120%);

  -webkit-backdrop-filter:
    blur(24px) saturate(120%);

  box-shadow:
    0 5px 20px rgba(125, 105, 55, 0.045),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
}

html[data-theme="dark"]
.off-compose-bar {
  background:
    rgba(47, 45, 40, 0.74);

  border-color:
    rgba(255, 255, 255, 0.10);

  box-shadow:
    0 5px 20px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}


/* =========================
   —— 发送按钮 ——
   ========================= */

.off-compose-send {
  background:
    linear-gradient(
      135deg,
      #f8e9b4,
      #f0d990
    );

  color:
    #fffdf4;

  border-radius:
    50%;

  box-shadow:
    0 4px 12px rgba(215, 184, 94, 0.17),
    inset 0 1px 0 rgba(255, 255, 255, 0.76);

  transition:
    transform 0.15s ease,
    box-shadow 0.15s ease;
}

.off-compose-send:hover {
  box-shadow:
    0 6px 16px rgba(215, 184, 94, 0.23),
    inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

.off-compose-send:active {
  transform:
    scale(0.92);
}


html[data-theme="dark"]
.off-compose-send {
  background:
    linear-gradient(
      135deg,
      #e6cf7c,
      #cdb365
    );

  color:
    #fffbea;

  box-shadow:
    0 4px 14px rgba(190, 160, 70, 0.25);
}


/* =========================
   —— 分割线 ——
   ========================= */

.off-list hr,
.off-app.off-app-session hr {
  border-color:
    rgba(160, 145, 100, 0.07);
}


/* =========================
   —— 滚动条 ——
   ========================= */

.off-app ::-webkit-scrollbar {
  width:
    5px;

  height:
    5px;
}

.off-app ::-webkit-scrollbar-thumb {
  background:
    rgba(218, 193, 112, 0.20);

  border-radius:
    999px;
}

.off-app ::-webkit-scrollbar-track {
  background:
    transparent;
}
